import{_ as e,o,c as a,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const n=JSON.parse('{"title":"1956年 · 合伙创业","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1956年.md","filePath":"05_quotes/by-year/1956年.md"}'),l={name:"05_quotes/by-year/1956年.md"};function u(q,t,s,c,_,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_1956年-·-合伙创业" tabindex="-1">1956年 · 合伙创业 <a class="header-anchor" href="#_1956年-·-合伙创业" aria-label="Permalink to &quot;1956年 · 合伙创业&quot;">​</a></h1><blockquote><p>&quot;我始终将主要注意力放在发现严重被低估的证券上。&quot;——巴菲特（26岁）</p></blockquote><p>本页收录1956年致合伙人信中的经典语录。26岁的巴菲特正式创立合伙企业，以格雷厄姆的價值投資理念为根基，开启了日后六十年的传奇序幕。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;我对整体市场水平的看法是，股价高于内在价值。如果这一观点正确，则意味着所有股票价格都可能出现大幅下跌，无论是否被低估。&quot;</p></blockquote><blockquote><p>&quot;如果市场回到被低估的状态，我们的资本可能会专门用于一般股票投资，届时或许还会使用一些借来的资金。相反，如果市场大幅上涨，我们的策略将是趁利润实现时减少一般股票投资，增加workout投资组合。&quot;</p></blockquote><blockquote><p>&quot;过去一年，我们持仓中有两个已经达到一定规模，有望参与公司决策……两者都可能需要三到五年的时间才能见效，但目前看来具有获得高平均年回报率的潜力，同时风险最小。&quot;</p></blockquote><blockquote><p>&quot;基本上，所有合伙企业都投资于相同的证券，比例也大致相同。然而，尤其是在初期阶段，资金在不同的市场时点和水平到位，因此业绩差异比未来年份可能更大。&quot;</p></blockquote><blockquote><p>&quot;多年来，只要业绩每年比指数好10%我就非常满意，所以对于这三个合伙企业来说，1957年是成功的一年，可能好于平均水平。&quot;</p></blockquote><blockquote><p>&quot;我们可以肯定地说，1957年底我们的投资组合比1956年底更具价值。这既是因为股价普遍较低，也是因为我们有更多时间来收购那些只能耐心才能获得的严重低估的证券。&quot;</p></blockquote><blockquote><p>&quot;在任何时候，我们投资组合的相当比例可能处于&#39;冻结&#39;状态。这一策略虽然需要耐心，但应该能最大化长期利润。&quot;</p></blockquote><blockquote><p>&quot;我可以肯定地说，1957年底我们的投资组合比1956年底更具价值。这既是因为股价普遍较低，也是因为我们有更多时间来收购那些只能耐心才能获得的严重低估的证券。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1956年5月1日，26岁的巴菲特在内布拉斯加州奥马哈创立了巴菲特联合有限公司（Buffett Partnership, Ltd.），首批7位有限合伙人包括家人和朋友，出资总额10.5万美元。合同明确规定了4%的保底利息和超过6%部分由巴菲特提成25%的分成机制，这是他日后六十年传奇的起点。同年底至1957年初，他又相继成立了两个新合伙企业，资金规模持续扩大。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1956年-翻译-·-01-letters-1956年-核心总结-·-01-letters-1956年-思维导图" tabindex="-1"><a href="/01_letters/1956年/翻译">01_letters/1956年/翻译</a> · <a href="/01_letters/1956年/核心总结">01_letters/1956年/核心总结</a> · <a href="/01_letters/1956年/思维导图">01_letters/1956年/思维导图</a> <a class="header-anchor" href="#_01-letters-1956年-翻译-·-01-letters-1956年-核心总结-·-01-letters-1956年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1956年/翻译]] · [[→ 核心总结|01_letters/1956年/核心总结]] · [[→ 思维导图|01_letters/1956年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1956年/翻译">/01_letters/1956年/翻译</a></li></ul>',21)])])}const p=e(l,[["render",u]]);export{n as __pageData,p as default};
